@Component("aircraftModel-handler")
@ProcessingGroup("aircraftModel-processing-group")
public class AircraftModelEventHandler {
	
	// core constructor
	AircraftModelEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAircraftModelEvent
     */
    @EventHandler
    public void handle( CreateAircraftModelEvent event) {
        entityManager.persist(new AircraftModel(event.getAircraftModelId(), event.getName(), event.getModelDesignation(), event.getFamily(), event.getVariants(), event.getEngineTypes(), event.getAircraftType()));
    }

    /*
     * @param	event UpdateAircraftModelEvent
     */
    @EventHandler
    public AircraftModel handle( UpdateAircraftModelEvent event) {
    	entityManager.merge(new AircraftModel(event.getAircraftModelId(), event.getName(), event.getModelDesignation(), event.getFamily(), event.getVariants(), event.getEngineTypes(), event.getAircraftType()));
    }
    
    /*
     * @param	event DeleteAircraftModelEvent
     */
    @EventHandler
    public void on( DeleteAircraftModelEvent event) {
    	AircraftModel entity = new AircraftModel();
   
    	// ------------------------------------------
    	// apply the AircraftModelId
    	// ------------------------------------------
    	entity.setAircraftModelId( event.getAircraftModelId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AircraftModelRepository aircraftModelEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AircraftModelEventHandler.class.getName());

}
